package httpapi

import (
	"context"
	"encoding/json"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/hkjang/moyro/server/internal/audit"
	"github.com/hkjang/moyro/server/internal/auth"
	"github.com/hkjang/moyro/server/internal/store"
	"github.com/hkjang/moyro/server/internal/teams"
	"github.com/hkjang/moyro/server/internal/ws"
)

// Ten team-administration endpoints gate on callerCanAdminTeam, which asks
// auth.HasRole and teams.IsTeamAdmin. Both of those read a roles column out of
// PostgreSQL, so both can fail for reasons that have nothing to do with the
// caller's standing: a dropped connection, a broken team_members table, a
// cancelled context.
//
// Folding those faults into the same 403 the endpoints give a non-admin is a
// lie the client cannot see through. 403 is permanent — no official client
// retries it — so a team admin whose database hiccuped is told, durably, that
// they are not a team admin. The sibling channel path already makes the
// opposite call: listChannelViews turns an IsMember fault into
// 500 api.context.permissions.app_error rather than a denial.
//
// This pins both halves of the split at once, through the real auth/teams/
// audit services and the chi patterns copied from router.go:
//   - a missing row is still an answer — a non-member and a deleted user get
//     the same 403 they always did, because pgx.ErrNoRows means "not an admin"
//   - anything else is a fault and must surface as 500, before the audit row,
//     the write and the broadcast
//
// Both denial strings are represented: compat_wave_handlers.go says "team
// admin required" and compat_wave_handlers_final.go says "team_admin
// required". They stay as they are; only the fault branch is new.
func TestTeamAdminCheckFaultIsNotForbidden(t *testing.T) {
	db := newOperationsTestDB(t)
	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()
	if err := store.Migrate(ctx, db); err != nil {
		t.Fatalf("migrate schema: %v", err)
	}
	seedSidebarHandlerFixture(t, ctx, db)
	// user-a administers team-main. user-b is a plain member, user-c is not on
	// the team at all, and user-gone is soft-deleted (HasRole's query filters
	// on delete_at=0, so it hands back pgx.ErrNoRows for them). user-victim,
	// user-target and user-leaver are removal/roles subjects.
	if _, err := db.Pool.Exec(ctx, `
		UPDATE team_members SET roles='team_user team_admin' WHERE team_id='team-main' AND user_id='user-a';
		INSERT INTO users (id, username, email, password_hash, roles, create_at, update_at)
		VALUES ('user-b', 'user-b', 'b@example.test', 'hash', 'system_user', 1, 1),
		       ('user-c', 'user-c', 'c@example.test', 'hash', 'system_user', 1, 1),
		       ('user-victim', 'user-victim', 'v@example.test', 'hash', 'system_user', 1, 1),
		       ('user-target', 'user-target', 't@example.test', 'hash', 'system_user', 1, 1),
		       ('user-leaver', 'user-leaver', 'l@example.test', 'hash', 'system_user', 1, 1);
		INSERT INTO users (id, username, email, password_hash, roles, create_at, update_at, delete_at)
		VALUES ('user-gone', 'user-gone', 'g@example.test', 'hash', 'system_user', 1, 1, 7);
		INSERT INTO team_members (team_id, user_id, roles, create_at)
		VALUES ('team-main', 'user-b', 'team_user', 1),
		       ('team-main', 'user-victim', 'team_user', 1),
		       ('team-main', 'user-target', 'team_user', 1),
		       ('team-main', 'user-leaver', 'team_user', 1),
		       ('team-main', 'user-gone', 'team_user', 1)
	`); err != nil {
		t.Fatalf("seed team admin actors: %v", err)
	}

	hub := ws.NewHub()
	hub.SetAudienceResolver(ws.DatabaseAudienceResolver(db))
	runCtx, cancelHub := context.WithCancel(ctx)
	t.Cleanup(cancelHub)
	go hub.Run(runCtx)

	h := &handlers{
		auth:  auth.New(db, []byte("team-admin-errors-signing-key!!!"), time.Hour, nil),
		teams: teams.New(db),
		audit: audit.New(db, slog.Default()),
		hub:   hub,
	}
	router := chi.NewRouter()
	router.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			actor := r.Header.Get("X-Test-Actor")
			next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userIDKey, actor)))
		})
	})
	// Patterns copied character for character from router.go:717/902/904/995.
	router.Put("/teams/{teamID}/members/{userID}/roles", h.setTeamMemberRoles)
	router.Delete("/teams/{teamID}/members/{userID}", h.removeTeamMember)
	router.Post("/teams/{teamID}/image", h.uploadTeamImage)
	router.Post("/teams/{teamID}/invite-guests/email", h.inviteGuestsByEmail)

	type teamAdminRoute struct {
		name   string
		method string
		// okPath is exercised by the admin and mutates; denyPath is the one
		// every refused actor uses, so a denial never disturbs the fixture.
		okPath    string
		denyPath  string
		body      string
		forbidden string
		// guestGated routes run denyGuestMutation first, which 401s a
		// soft-deleted actor before the admin check is ever reached.
		guestGated bool
	}
	routes := []teamAdminRoute{
		{
			name: "set member roles", method: http.MethodPut,
			okPath: "/teams/team-main/members/user-target/roles", denyPath: "/teams/team-main/members/user-target/roles",
			body: `{"roles":"team_user team_admin"}`, forbidden: "team admin required", guestGated: true,
		},
		{
			name: "remove member", method: http.MethodDelete,
			okPath: "/teams/team-main/members/user-victim", denyPath: "/teams/team-main/members/user-target",
			forbidden: "team_admin required", guestGated: true,
		},
		{
			name: "upload team image", method: http.MethodPost,
			okPath: "/teams/team-main/image", denyPath: "/teams/team-main/image",
			forbidden: "team_admin required",
		},
		{
			name: "invite guests by email", method: http.MethodPost,
			okPath: "/teams/team-main/invite-guests/email", denyPath: "/teams/team-main/invite-guests/email",
			forbidden: "team_admin required",
		},
	}

	// The admin's answer is the baseline every refusal below is measured
	// against; it has to keep working unchanged.
	for _, rt := range routes {
		t.Run(rt.name+" answers the team admin", func(t *testing.T) {
			rr := serveTeamAdminRequest(router, rt.method, rt.okPath, "user-a", rt.body)
			if rr.Code != http.StatusOK {
				t.Fatalf("status = %d, want 200 (body %s)", rr.Code, rr.Body.String())
			}
		})
	}

	// A plain member and a stranger are both "not an admin" — pgx.ErrNoRows on
	// team_members must not be promoted to a fault.
	for _, rt := range routes {
		for _, actor := range []string{"user-b", "user-c"} {
			t.Run(rt.name+" refuses "+actor, func(t *testing.T) {
				rr := serveTeamAdminRequest(router, rt.method, rt.denyPath, actor, rt.body)
				assertTeamAdminError(t, rr, http.StatusForbidden, "api.context.permissions.app_error", rt.forbidden)
			})
		}
		if rt.guestGated {
			continue
		}
		// A soft-deleted actor makes HasRole itself return pgx.ErrNoRows. That
		// is the other half of the guard: still 403, never 500.
		t.Run(rt.name+" refuses a deleted user", func(t *testing.T) {
			rr := serveTeamAdminRequest(router, rt.method, rt.denyPath, "user-gone", rt.body)
			assertTeamAdminError(t, rr, http.StatusForbidden, "api.context.permissions.app_error", rt.forbidden)
		})
	}

	// Leaving a team of your own accord never consults the admin check at all
	// (removeTeamMember short-circuits on uid == caller). Pin that here so the
	// fault assertion below can tell the two paths apart.
	t.Run("a member may still remove themselves", func(t *testing.T) {
		rr := serveTeamAdminRequest(router, http.MethodDelete, "/teams/team-main/members/user-leaver", "user-leaver", "")
		if rr.Code != http.StatusOK {
			t.Fatalf("self-removal status = %d, want 200 (body %s)", rr.Code, rr.Body.String())
		}
	})

	// Observe the successful audit rows before breaking anything, so the
	// "no row for a refused caller" assertion is not just a race we won.
	for _, want := range []struct{ action, target string }{
		{audit.ActionTeamMemberRoles, "user-target"},
		{audit.ActionTeamImageUpload, "team-main"},
		{audit.ActionTeamInviteGuests, "team-main"},
	} {
		waitForAuditRow(t, ctx, db, want.action, want.target)
	}

	// Now the fault. Dropping team_members inside this test's private schema
	// leaves users intact, so HasRole still answers normally and the only
	// broken step in the request is teams.IsTeamAdmin — one fault, one
	// observable.
	if _, err := db.Pool.Exec(ctx, `DROP TABLE team_members CASCADE`); err != nil {
		t.Fatalf("drop team_members: %v", err)
	}
	for _, rt := range routes {
		t.Run(rt.name+" reports the team admin lookup fault", func(t *testing.T) {
			rr := serveTeamAdminRequest(router, rt.method, rt.denyPath, "user-c", rt.body)
			assertTeamAdminError(t, rr, http.StatusInternalServerError,
				"api.context.permissions.app_error", "failed to check team admin permissions")
		})
	}

	// Self-removal still does not ask about team administration, so it fails
	// further down with its own error id rather than the permissions one.
	t.Run("self-removal still skips the team admin lookup", func(t *testing.T) {
		rr := serveTeamAdminRequest(router, http.MethodDelete, "/teams/team-main/members/user-c", "user-c", "")
		if id := decodeErrorID(t, rr); id != "api.team.member.remove.app_error" {
			t.Fatalf("error id = %q, want the removal error rather than a permissions verdict (body %s)",
				id, rr.Body.String())
		}
	})

	// A request that never got past the permission check has nothing to
	// record. Watch past LogAsync's three-second database timeout.
	deadline := time.Now().Add(3200 * time.Millisecond)
	for {
		var count int
		if err := db.Pool.QueryRow(ctx,
			`SELECT count(*) FROM audit_logs WHERE actor_id='user-c'`).Scan(&count); err != nil {
			t.Fatalf("count refused-caller audit rows: %v", err)
		}
		if count != 0 {
			t.Fatalf("audit rows for the refused caller = %d, want none", count)
		}
		if time.Now().After(deadline) {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
}

func serveTeamAdminRequest(router http.Handler, method, path, actor, body string) *httptest.ResponseRecorder {
	r := httptest.NewRequest(method, path, strings.NewReader(body))
	r.Header.Set("X-Test-Actor", actor)
	rr := httptest.NewRecorder()
	router.ServeHTTP(rr, r)
	return rr
}

func assertTeamAdminError(t *testing.T, rr *httptest.ResponseRecorder, status int, id, message string) {
	t.Helper()
	if rr.Code != status {
		t.Fatalf("status = %d, want %d (body %s)", rr.Code, status, rr.Body.String())
	}
	var body apiError
	if err := json.Unmarshal(rr.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode error body %q: %v", rr.Body.String(), err)
	}
	if body.ID != id || body.Message != message {
		t.Fatalf("error = %q/%q, want %q/%q", body.ID, body.Message, id, message)
	}
}
package httpapi

import (
	"context"
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/hkjang/moyro/server/internal/audit"
	"github.com/hkjang/moyro/server/internal/auth"
	"github.com/hkjang/moyro/server/internal/store"
	"github.com/hkjang/moyro/server/internal/teams"
)

// The three multipart upload stubs — POST /teams/{teamID}/image, POST
// /bots/{botUserID}/icon and POST /uploads/{uploadID} — cap their request body
// with http.MaxBytesReader and then drain it. Draining is the whole point:
// none of them persists bytes yet, they just have to not hang the official
// client's upload form on EOF.
//
// What they must not do is swallow the cap. An io.Copy that stops because the
// reader refused to hand over byte N+1 has not received the upload, so a 200
// plus an audit row is two lies at once: the client believes its icon landed,
// and the operator reads an upload in the audit log that never happened.
// uploadChunk adds a third — it reports the truncated byte count as
// file_offset, which is exactly the number a resuming client uses as its next
// offset.
//
// This exercises the production chi patterns copied verbatim from
// router.go:904/957-959/977 rather than calling the handlers directly: the
// bot-icon audit target is read out of a URL parameter, so a test that
// registered a convenient pattern name would hide that half of the defect.
func TestUploadStubsRefuseOversizedBodies(t *testing.T) {
	db := newOperationsTestDB(t)
	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()
	if err := store.Migrate(ctx, db); err != nil {
		t.Fatalf("migrate schema: %v", err)
	}
	seedSidebarHandlerFixture(t, ctx, db)
	// user-a administers team-main; sysadmin carries the global role the two
	// bot-icon routes gate on. Both go through the real auth/teams services.
	if _, err := db.Pool.Exec(ctx, `
		UPDATE team_members SET roles='team_user team_admin' WHERE team_id='team-main' AND user_id='user-a';
		INSERT INTO users (id, username, email, password_hash, roles, create_at, update_at)
		VALUES ('sysadmin', 'sysadmin', 'sysadmin@example.test', 'hash', 'system_user system_admin', 1, 1)
	`); err != nil {
		t.Fatalf("seed upload stub actors: %v", err)
	}

	h := &handlers{
		auth:  auth.New(db, []byte("upload-stub-limits-signing-key!!"), time.Hour, nil),
		teams: teams.New(db),
		audit: audit.New(db, slog.Default()),
	}
	// Patterns are copied character for character from router.go so the
	// handlers read the parameter names production gives them.
	router := chi.NewRouter()
	router.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			actor := r.Header.Get("X-Test-Actor")
			next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userIDKey, actor)))
		})
	})
	router.Post("/teams/{teamID}/image", h.uploadTeamImage)
	router.Post("/bots/{botUserID}/icon", h.uploadBotIcon)
	router.Delete("/bots/{botUserID}/icon", h.deleteBotIcon)
	router.Post("/uploads/{uploadID}", h.uploadChunk)

	const smallBody = 512

	type stub struct {
		name     string
		method   string
		path     string
		actor    string
		limit    int64
		errID    string
		action   string
		target   string
		wantBody func(t *testing.T, rr *httptest.ResponseRecorder)
	}
	stubs := []stub{
		{
			name: "team image", method: http.MethodPost, path: "/teams/team-main/image",
			actor: "user-a", limit: 10 << 20,
			errID:  "api.team.image.upload_too_large",
			action: audit.ActionTeamImageUpload, target: "team-main",
			wantBody: assertStatusOKEnvelope,
		},
		{
			name: "bot icon", method: http.MethodPost, path: "/bots/bot-alpha/icon",
			actor: "sysadmin", limit: 256 << 10,
			errID:  "api.bot.icon.upload_too_large",
			action: audit.ActionBotIconUpload, target: "bot-alpha",
			wantBody: assertStatusOKEnvelope,
		},
		{
			name: "upload chunk", method: http.MethodPost, path: "/uploads/upload-7",
			actor: "user-a", limit: 50 << 20,
			errID:  "api.upload.chunk.too_large",
			action: audit.ActionUploadChunk, target: "upload-7",
			wantBody: func(t *testing.T, rr *httptest.ResponseRecorder) {
				t.Helper()
				var body struct {
					ID         string `json:"id"`
					FileOffset int64  `json:"file_offset"`
				}
				if err := json.Unmarshal(rr.Body.Bytes(), &body); err != nil {
					t.Fatalf("decode chunk body %q: %v", rr.Body.String(), err)
				}
				if body.ID != "upload-7" || body.FileOffset != smallBody {
					t.Fatalf("chunk body = %+v, want id upload-7 and file_offset %d", body, smallBody)
				}
			},
		},
	}
	// A body inside the cap keeps its existing contract: 200, the documented
	// envelope, and one audit row. These are the rows the oversized assertions
	// below are measured against, so they have to land first.
	for _, s := range stubs {
		t.Run(s.name+" accepts a body inside the cap", func(t *testing.T) {
			rr := serveUploadStub(router, s.method, s.path, s.actor, smallBody)
			if rr.Code != http.StatusOK {
				t.Fatalf("status = %d, want 200 (body %s)", rr.Code, rr.Body.String())
			}
			s.wantBody(t, rr)
		})
	}

	// DELETE /bots/{botUserID}/icon never had a body to drain, but it reads the
	// same URL parameter for its audit target, so it pins the parameter name
	// alongside the upload path.
	deleteRecorder := serveUploadStub(router, http.MethodDelete, "/bots/bot-alpha/icon", "sysadmin", 0)
	if deleteRecorder.Code != http.StatusOK {
		t.Fatalf("delete bot icon: status = %d, want 200 (body %s)", deleteRecorder.Code, deleteRecorder.Body.String())
	}
	assertStatusOKEnvelope(t, deleteRecorder)

	// LogAsync writes on its own goroutine; observe every success row (and the
	// target it recorded) before asserting that the refusals add none. Each
	// wait is its own subtest so one wrong target doesn't hide the rest.
	wantRows := []struct{ action, target string }{
		{audit.ActionTeamImageUpload, "team-main"},
		{audit.ActionBotIconUpload, "bot-alpha"},
		{audit.ActionBotIconDelete, "bot-alpha"},
		{audit.ActionUploadChunk, "upload-7"},
	}
	for _, want := range wantRows {
		t.Run(want.action+" audit row names its subject", func(t *testing.T) {
			waitForAuditRow(t, ctx, db, want.action, want.target)
		})
	}

	// Now overrun each cap by a single byte. Nothing is stored, so the only
	// observable difference between "received" and "refused" is the answer.
	for _, s := range stubs {
		t.Run(s.name+" refuses a body past the cap", func(t *testing.T) {
			rr := serveUploadStub(router, s.method, s.path, s.actor, s.limit+1)
			if rr.Code != http.StatusRequestEntityTooLarge {
				t.Fatalf("status = %d, want 413 (body %s)", rr.Code, rr.Body.String())
			}
			if id := decodeErrorID(t, rr); id != s.errID {
				t.Fatalf("error id = %q, want %q", id, s.errID)
			}
			if strings.Contains(rr.Body.String(), "file_offset") {
				t.Fatalf("refusal body %s must not hand back a resume offset", rr.Body.String())
			}
		})
	}

	// Watch past LogAsync's three-second database timeout: a refused request
	// must leave the audit log holding only the successful one.
	deadline := time.Now().Add(3200 * time.Millisecond)
	for {
		for _, want := range wantRows {
			var count int
			if err := db.Pool.QueryRow(ctx,
				`SELECT count(*) FROM audit_logs WHERE action=$1`, want.action).Scan(&count); err != nil {
				t.Fatalf("count %s audit rows: %v", want.action, err)
			}
			if count != 1 {
				t.Fatalf("%s audit rows = %d, want only the accepted request", want.action, count)
			}
		}
		if time.Now().After(deadline) {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
}

// serveUploadStub drives the router with a body of exactly size bytes. The
// body streams rather than materializing, so the 50MB chunk cap costs one
// buffer instead of 50MB of heap under -race.
func serveUploadStub(router http.Handler, method, path, actor string, size int64) *httptest.ResponseRecorder {
	var body io.Reader
	if size > 0 {
		body = io.LimitReader(uploadStubFiller{}, size)
	}
	r := httptest.NewRequest(method, path, body)
	r.Header.Set("X-Test-Actor", actor)
	rr := httptest.NewRecorder()
	router.ServeHTTP(rr, r)
	return rr
}

// uploadStubFiller is an endless source of a single repeated byte — enough to
// push a drain past its cap without holding the payload in memory.
type uploadStubFiller struct{}

func (uploadStubFiller) Read(p []byte) (int, error) {
	for i := range p {
		p[i] = 'x'
	}
	return len(p), nil
}

func assertStatusOKEnvelope(t *testing.T, rr *httptest.ResponseRecorder) {
	t.Helper()
	var body struct {
		Status string `json:"status"`
	}
	if err := json.Unmarshal(rr.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode envelope %q: %v", rr.Body.String(), err)
	}
	if body.Status != "OK" {
		t.Fatalf("body = %s, want {\"status\":\"OK\"}", rr.Body.String())
	}
}

func waitForAuditRow(t *testing.T, ctx context.Context, db *store.DB, action, target string) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		var count int
		if err := db.Pool.QueryRow(ctx,
			`SELECT count(*) FROM audit_logs WHERE action=$1 AND target=$2`, action, target).Scan(&count); err != nil {
			t.Fatalf("count %s audit rows: %v", action, err)
		}
		if count == 1 {
			return
		}
		if time.Now().After(deadline) {
			var observed string
			_ = db.Pool.QueryRow(ctx,
				`SELECT coalesce(string_agg(coalesce(quote_literal(target), 'NULL'), ','), '<no rows>')
				 FROM audit_logs WHERE action=$1`,
				action).Scan(&observed)
			t.Fatalf("%s audit row with target %q never arrived (observed targets: %s)", action, target, observed)
		}
		time.Sleep(10 * time.Millisecond)
	}
}

// must hold team_admin for that team OR be system_admin globally OR be
// removing themselves (Leave). Self-removal is allowed because every
// user can leave any team they're in.
func (h *handlers) removeTeamMember(w http.ResponseWriter, r *http.Request) {
	if chi.URLParam(r, "userID") != userID(r) && h.denyGuestMutation(w, r, "api.team.members.remove.guest_forbidden") {
		return
	}
	caller := userID(r)
	if caller == "" {
		writeError(w, 401, "api.context.session_expired.app_error", "missing token")
		return
	}
	tid := chi.URLParam(r, "teamID")
	uid := chi.URLParam(r, "userID")
	if uid == "" {
		writeError(w, 400, "api.team.member.remove.app_error", "missing user")
		return
	}
	// Self-removal is Leave: it never asks about team administration, so it
	// must not touch the roles tables at all.
	if uid != caller && !h.requireTeamAdmin(w, r, tid, caller, "team_admin required") {
		return
	}
	changed, err := h.teams.RemoveMember(r.Context(), tid, uid)
	if err != nil {
		writeError(w, 500, "api.team.member.remove.app_error", err.Error())
		return
	}
	if !changed {
		writeError(w, 404, "api.team.member.remove.not_found", "membership not found")
		return
	}
	if h.audit != nil {
		h.audit.LogAsync(caller, audit.ActionTeamMemberRemove, tid+":"+uid, nil)
	}
	writeJSON(w, 200, map[string]any{"status": "OK"})
}

// deleteTeamImage — DELETE /teams/{teamID}/image
// Stub: we don't store team images yet (the table has no image column).
// Returns 200 with the documented success envelope so the admin
// console's "Remove team icon" button doesn't error-toast.
func (h *handlers) deleteTeamImage(w http.ResponseWriter, r *http.Request) {
	if h.denyGuestMutation(w, r, "api.team.image.guest_forbidden") {
		return
	}
	if !h.requireTeamAdmin(w, r, chi.URLParam(r, "teamID"), userID(r), "team_admin required") {
		return
	}
	if h.audit != nil {
		h.audit.LogAsync(userID(r), audit.ActionTeamImageDelete, chi.URLParam(r, "teamID"), nil)
	}
	writeJSON(w, 200, map[string]any{"status": "OK"})
}

// uploadTeamImage — POST /teams/{teamID}/image
// Stub. Reads-and-discards the multipart body so the official admin
// console's drag-drop upload form doesn't hang on EOF; future work
// would tie this into the existing files.Service backend.
func (h *handlers) uploadTeamImage(w http.ResponseWriter, r *http.Request) {
	if !h.requireTeamAdmin(w, r, chi.URLParam(r, "teamID"), userID(r), "team_admin required") {
		return
	}
	// Cap at 10MB then drain — protects against a runaway upload while
	// the stub doesn't persist anything. A body past the cap was never
	// received, so it gets 413 instead of a success envelope and an audit
	// row for an upload that didn't happen.
	if _, ok := drainCappedBody(w, r, 10<<20, "api.team.image.upload_too_large"); !ok {
		return
	}
	if h.audit != nil {
		h.audit.LogAsync(userID(r), audit.ActionTeamImageUpload, chi.URLParam(r, "teamID"), nil)
	}
	writeJSON(w, 200, map[string]any{"status": "OK"})
}

package httpapi

import (
	"errors"
	"net/http"

	"github.com/hkjang/moyro/server/internal/files"
)

// denyGuestMutation centralises the collaboration boundary for operations
// that could expand a restricted guest's scope. Channel membership itself is
// the allow-list, but guests must not create or discover other spaces, start
// DMs, or add/remove other members.
func (h *handlers) denyGuestMutation(w http.ResponseWriter, r *http.Request, errorID string) bool {
	u, err := h.auth.UserByID(r.Context(), userID(r))
	if err != nil {
		writeError(w, http.StatusUnauthorized, errorID, "active user session required")
		return true
	}
	if !u.IsGuest() {
		return false
	}
	writeError(w, http.StatusForbidden, errorID, "guest access is restricted to invited channels")
	return true
}

func (h *handlers) denyGuestEnumeration(w http.ResponseWriter, r *http.Request, errorID string) bool {
	u, err := h.auth.UserByID(r.Context(), userID(r))
	if err != nil {
		writeError(w, http.StatusUnauthorized, errorID, "active user session required")
		return true
	}
	if !u.IsGuest() {
		return false
	}
	writeError(w, http.StatusForbidden, errorID, "team-wide enumeration is unavailable to guests")
	return true
}

func (h *handlers) guestMayViewUser(w http.ResponseWriter, r *http.Request, targetID, errorID string) bool {
	return h.guestMayViewUserWithStatus(w, r, targetID, errorID, http.StatusForbidden)
}

// guestMayViewNamedUser makes a hidden-by-name/email account indistinguishable
// from a missing account. Returning 403 here would let a restricted guest use
// the lookup endpoint as a directory-existence oracle.
func (h *handlers) guestMayViewNamedUser(w http.ResponseWriter, r *http.Request, targetID, errorID string) bool {
	return h.guestMayViewUserWithStatus(w, r, targetID, errorID, http.StatusNotFound)
}

func (h *handlers) guestMayViewUserWithStatus(w http.ResponseWriter, r *http.Request, targetID, errorID string, hiddenStatus int) bool {
	actor, err := h.auth.UserByID(r.Context(), userID(r))
	if err != nil {
		writeError(w, http.StatusUnauthorized, errorID, "active user session required")
		return false
	}
	if !actor.IsGuest() {
		return true
	}
	allowed, err := h.auth.CanGuestSeeUser(r.Context(), actor.ID, targetID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, errorID, "guest visibility could not be checked")
		return false
	}
	if !allowed {
		if hiddenStatus == http.StatusNotFound {
			writeError(w, hiddenStatus, errorID, "user not found")
		} else {
			writeError(w, hiddenStatus, errorID, "user does not share an invited channel")
		}
		return false
	}
	return true
}

// authorizeOriginalFile applies channel membership first, then the guest's
// explicit original-download grant. Metadata and inline thumbnails/previews
// continue to use authorizeFile so image-bearing collaboration still works.
func (h *handlers) authorizeOriginalFile(r *http.Request, fi *files.FileInfo) error {
	if err := h.authorizeFile(r, fi); err != nil {
		return err
	}
	allowed, err := h.auth.CanDownloadFiles(r.Context(), userID(r))
	if err != nil {
		return err
	}
	if !allowed {
		return errors.New("original file downloads are disabled for this guest")
	}
	return nil
}
